-- ============================================================================
-- DEMO / SEED DATA — NOT PRODUCTION DATA
-- Fictional schools, jobs and teacher profiles used to make the public jobs
-- page and dashboards look realistic during demos.
-- Everything below is owned by demo accounts on the @jivorna-demo.test domain
-- and every school id starts with 'dddddddd-'. To strip this data later:
--   DELETE FROM public.jobs  WHERE school_id IN (SELECT id FROM public.schools WHERE id::text LIKE 'dddddddd-%');
--   DELETE FROM public.schools WHERE id::text LIKE 'dddddddd-%';
--   -- then delete the @jivorna-demo.test auth accounts.
-- ============================================================================

-- Seeding runs without an authenticated admin, so pause the publish gate and
-- the job-match notification fan-out for the duration of this migration.
ALTER TABLE public.jobs DISABLE TRIGGER enforce_job_publish_is_admin;
ALTER TABLE public.jobs DISABLE TRIGGER jobs_notify_match;

-- ---------------------------------------------------------------- schools ---

-- ------------------------------------------------------------------- jobs ---

ALTER TABLE public.jobs ENABLE TRIGGER jobs_notify_match;
ALTER TABLE public.jobs ENABLE TRIGGER enforce_job_publish_is_admin;

-- -------------------------------------------------------- teacher profiles ---
-- Demo teacher accounts already have blank profile rows created at sign-up.
ON CONFLICT (user_id) DO UPDATE SET
  full_name = EXCLUDED.full_name, email = EXCLUDED.email, phone = EXCLUDED.phone,
  headline = EXCLUDED.headline, bio = EXCLUDED.bio, subjects = EXCLUDED.subjects,
  grades = EXCLUDED.grades, boards = EXCLUDED.boards, languages = EXCLUDED.languages,
  experience_years = EXCLUDED.experience_years, qualification = EXCLUDED.qualification,
  current_school = EXCLUDED.current_school, city = EXCLUDED.city, state = EXCLUDED.state,
  location = EXCLUDED.location, expected_salary = EXCLUDED.expected_salary,
  current_salary = EXCLUDED.current_salary, notice_period_days = EXCLUDED.notice_period_days,
  available = EXCLUDED.available, available_from = EXCLUDED.available_from,
  status = EXCLUDED.status;
